// Validar que CV fue proporcionado
if (!$node.webhook_receive_application.binary.cv) {
  return { valid: false, error: 'CV_NOT_PROVIDED' };
}

const cvFile = $node.webhook_receive_application.binary.cv[0];

// Validar MIME type
if (cvFile.mimeType !== 'application/pdf') {
  return { valid: false, error: 'CV_INVALID_FORMAT' };
}

// Validar tamaño (máximo 10MB)
if (cvFile.data.length > 10485760) {
  return { valid: false, error: 'CV_TOO_LARGE' };
}

return { valid: true, mimeType: cvFile.mimeType };

// Nota: En un MVP real, usaríamos pdfparse o similar
// Por ahora, simulamos extracción básica
// En producción, esto debería ser un nodo especializado

const cvText = `Candidato: ${ $json.body.nombre }
Experiencia: ${ $json.body.experiencia_declarada } años
Tecnologías: ${ $json.body.habilidades_declaradas }`;

if (!cvText || cvText.length < 50) {
  return { readable: false, text: null };
}

return { readable: true, text: cvText };

const candidateData = $node.ai_extract_cv.json;
const scoringCriteria = $node.db_get_vacancy.json.scoring_criteria || [
  { name: 'Java', weight: 25, required: true },
  { name: 'Spring Boot', weight: 20, required: true },
  { name: 'SQL', weight: 15, required: true },
  { name: 'REST API', weight: 15, required: false },
  { name: 'Git', weight: 10, required: false },
  { name: 'Experiencia', weight: 15, required: false }
];

let totalScore = 0;
const criteriaResults = [];

// Evaluar tecnologías
if (candidateData.habilidades) {
  for (const skill of candidateData.habilidades) {
    const criterion = scoringCriteria.find(c => 
      c.name.toLowerCase() === skill.nombre.toLowerCase()
    );

    if (criterion) {
      if (skill.evidencia_laboral) {
        criteriaResults.push({
          nombre: criterion.name,
          peso: criterion.weight,
          puntos: criterion.weight,
          cumple: true
        });
        totalScore += criterion.weight;
      } else {
        criteriaResults.push({
          nombre: criterion.name,
          peso: criterion.weight,
          puntos: 0,
          cumple: false
        });
      }
    }
  }
}

// Evaluar experiencia
const experienciaReq = 2; // 2 años
if (candidateData.experiencia_anios) {
  const expPoints = Math.min(candidateData.experiencia_anios / experienciaReq, 1) * 15;
  criteriaResults.push({
    nombre: 'Experiencia',
    peso: 15,
    puntos: expPoints,
    cumple: candidateData.experiencia_anios >= experienciaReq
  });
  totalScore += expPoints;
}

// Determinar prioridad
let prioridad = 'BAJA';
if (totalScore >= 80) prioridad = 'ALTA';
else if (totalScore >= 60) prioridad = 'MEDIA';

return {
  score: Math.min(totalScore, 100),
  prioridad: prioridad,
  criterios: criteriaResults
};

